const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT = path.resolve(String($env.OPENCLAW_ASSET_SHARED_ROOT || '/data/openclaw-assets'));
const MAX_ORPHAN_REPAIRS = 2;
const usableStatuses = new Set([
  'accepted', 'accepted_fallback', 'accepted_fallback_unreviewed'
]);

function atomicJson(filePath, value) {
  const tmp = `${filePath}.${Date.now()}.${Math.random().toString(16).slice(2)}.tmp`;
  fs.writeFileSync(tmp, JSON.stringify(value, null, 2), 'utf8');
  fs.renameSync(tmp, filePath);
}

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function readDependencyStates(jobDir) {
  const dir = path.join(jobDir, '_dependency_state');
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir)
    .filter((name) => name.endsWith('.json'))
    .map((name) => {
      try { return readJson(path.join(dir, name)); } catch { return null; }
    })
    .filter(Boolean);
}

function updateReferenceRegistry(projectDir, job, accepted, failed) {
  const registryPath = path.join(projectDir, 'reference_registry.json');
  let registry = {
    schema_version: '2.1',
    project_id: job.project_id,
    updated_at: new Date().toISOString(),
    assets: {}
  };
  if (fs.existsSync(registryPath)) {
    try {
      const existing = readJson(registryPath);
      registry = {
        ...registry,
        ...existing,
        assets: existing.assets ?? {}
      };
    } catch {}
  }
  const allowProvisional = job.reference_policy?.allow_provisional_references === true;
  for (const item of accepted) {
    const approved = item.final_status === 'accepted';
    registry.assets[item.asset_id] = {
      asset_id: item.asset_id,
      parent_asset_id: item.parent_asset_id ?? null,
      family_id: item.family_id ?? null,
      asset_code: item.asset_code ?? null,
      generation_stage: item.generation_stage ?? 'derived',
      category: item.category,
      name: item.name,
      job_id: job.job_id,
      filename: item.filename,
      path: item.absolute_path,
      relative_path: path.relative(projectDir, item.absolute_path),
      final_status: item.final_status,
      status: approved ? 'approved' : 'rejected',
      registry_status: approved ? 'approved' : 'provisional',
      reference_eligible: approved,
      payload_sha256: job.payload_sha256 ?? item.payload_sha256 ?? null,
      asset_role: item.asset_role ?? null,
      asset_kind: item.asset_kind ?? null,
      angle_id: item.angle_id ?? null,
      layout_type: item.layout_type ?? null,
      contains_multiple_independent_assets: item.contains_multiple_independent_assets === true,
      aspect_ratio: item.aspect_ratio ?? null,
      lock_id: item.lock_id ?? null,
      lock_hash: item.lock_hash ?? null,
      prompt_policy: item.prompt_policy ?? null,
      anchor_roles: item.anchor_roles ?? [],
      depends_on: item.depends_on ?? [],
      reference_inputs: item.reference_inputs ?? [],
      resolved_reference_inputs: item.resolved_reference_inputs ?? [],
      sha256: item.sha256,
      file_size: item.file_size,
      qa_score: item.n8n_review_score,
      qa_evidence: item.qa_evidence ?? null,
      generation_provider: item.generation_provider ?? null,
      provider_model: item.provider_model ?? null,
      updated_at: new Date().toISOString()
    };
  }
  for (const failure of failed) {
    const asset = (job.assets ?? []).find((item) => item.asset_id === failure.asset_id) ?? {};
    registry.assets[failure.asset_id] = {
      ...(registry.assets[failure.asset_id] ?? {}),
      asset_id: failure.asset_id,
      parent_asset_id: asset.parent_asset_id ?? null,
      family_id: asset.family_id ?? null,
      asset_code: asset.asset_code ?? null,
      generation_stage: asset.generation_stage ?? 'derived',
      category: asset.category ?? 'other',
      asset_role: asset.asset_role ?? null,
      asset_kind: asset.asset_kind ?? null,
      angle_id: asset.angle_id ?? null,
      layout_type: asset.layout_type ?? null,
      contains_multiple_independent_assets: asset.contains_multiple_independent_assets === true,
      lock_id: asset.lock_id ?? null,
      lock_hash: asset.lock_hash ?? null,
      name: asset.name ?? failure.asset_id,
      job_id: job.job_id,
      final_status: failure.final_status ?? 'failed_unknown',
      status: 'failed',
      registry_status: 'failed',
      payload_sha256: job.payload_sha256 ?? null,
      reference_eligible: false,
      final_reason: failure.final_reason ?? null,
      updated_at: new Date().toISOString()
    };
  }
  registry.schema_version = '2.1';
  registry.updated_at = new Date().toISOString();
  atomicJson(registryPath, registry);
  return {
    registryPath,
    registryFilename: 'reference_registry.json',
    approved_count: Object.values(registry.assets).filter((item) => (item.status ?? item.registry_status) === 'approved').length,
    provisional_count: Object.values(registry.assets).filter((item) => item.registry_status === 'provisional').length,
    failed_count: Object.values(registry.assets).filter((item) => (item.status ?? item.registry_status) === 'failed').length
  };
}

function sha256(filePath) {
  const hash = crypto
    .createHash('sha256')
    .update(fs.readFileSync(filePath))
    .digest('hex');
  return `sha256:${hash}`;
}

function countJson(dir) {
  return fs.existsSync(dir)
    ? fs.readdirSync(dir).filter((name) => name.endsWith('.json')).length
    : 0;
}

function taskMatches(filePath, assetId) {
  try {
    return readJson(filePath).asset_id === assetId;
  } catch {
    return false;
  }
}

function hasRunningAsset(jobDir, assetId) {
  const runningDir = path.join(jobDir, '_running');
  if (!fs.existsSync(runningDir)) return false;
  return fs.readdirSync(runningDir)
    .filter((name) => name.endsWith('.json'))
    .some((name) => taskMatches(path.join(runningDir, name), assetId));
}

function createFreshTask(jobDir, job, asset, repairCount) {
  return {
    schema_version: '3.0',
    project_id: job.project_id,
    job_id: job.job_id,
    output_dir: jobDir,
    ...asset,
    retry_count: 0,
    image_generation_count: 0,
    review_retry_count: 0,
    review_api_retry_count: 0,
    review_api_max_retries: 3,
    qa_feedback: '',
    review_history: [],
    worker_execution_count: 0,
    orphan_repair_count: repairCount,
    not_before: 0,
    queued_at: new Date().toISOString(),
  };
}

function repairMissingAsset(jobDir, job, asset) {
  const assetId = asset.asset_id;
  const queueDir = path.join(jobDir, '_queue');
  const runningDir = path.join(jobDir, '_running');
  const doneDir = path.join(jobDir, '_queue_done');
  const repairDir = path.join(jobDir, '_repair');
  fs.mkdirSync(queueDir, { recursive: true });
  fs.mkdirSync(runningDir, { recursive: true });
  fs.mkdirSync(doneDir, { recursive: true });
  fs.mkdirSync(repairDir, { recursive: true });

  const queuePath = path.join(queueDir, `${assetId}.json`);
  if (fs.existsSync(queuePath) || hasRunningAsset(jobDir, assetId)) {
    return { repaired: false, reason: 'already_queued_or_running' };
  }

  const repairPath = path.join(repairDir, `${assetId}.json`);
  const repairState = fs.existsSync(repairPath)
    ? readJson(repairPath)
    : { count: 0, history: [] };
  const count = Number(repairState.count ?? 0);
  if (count >= MAX_ORPHAN_REPAIRS) {
    return { repaired: false, reason: 'repair_budget_exhausted' };
  }

  const nextCount = count + 1;
  const donePath = path.join(doneDir, `${assetId}.json`);
  let task;
  let source;
  if (fs.existsSync(donePath)) {
    try {
      task = readJson(donePath);
      source = 'queue_done';
    } catch {
      task = null;
    }
  }
  if (!task) {
    task = createFreshTask(jobDir, job, asset, nextCount);
    source = 'job_json';
  }

  task.not_before = 0;
  task.lease_id = null;
  task.running_task_path = null;
  task.orphan_repair_count = nextCount;
  task.orphan_repaired_at = new Date().toISOString();

  if (fs.existsSync(donePath)) {
    atomicJson(donePath, task);
    fs.renameSync(donePath, queuePath);
  } else {
    atomicJson(queuePath, task);
  }

  const event = {
    count: nextCount,
    source,
    repaired_at: new Date().toISOString(),
  };
  atomicJson(repairPath, {
    asset_id: assetId,
    count: nextCount,
    max_repairs: MAX_ORPHAN_REPAIRS,
    history: [...(repairState.history ?? []), event].slice(-10),
  });
  return { repaired: true, reason: source, count: nextCount };
}

function acquireCallback(jobDir) {
  const sentPath = path.join(jobDir, '.callback_sent');
  if (fs.existsSync(sentPath)) return false;
  const inflightPath = path.join(jobDir, '.callback_inflight');
  if (fs.existsSync(inflightPath)) {
    const age = Date.now() - fs.statSync(inflightPath).mtimeMs;
    if (age < 5 * 60 * 1000) return false;
    const logDir = path.join(jobDir, '_logs');
    fs.mkdirSync(logDir, { recursive: true });
    fs.renameSync(
      inflightPath,
      path.join(logDir, `callback_inflight_stale_${Date.now()}.json`)
    );
  }
  try {
    const fd = fs.openSync(inflightPath, 'wx');
    fs.writeFileSync(fd, JSON.stringify({ acquired_at: new Date().toISOString() }));
    fs.closeSync(fd);
    return true;
  } catch {
    return false;
  }
}

const output = [];
if (!fs.existsSync(ROOT)) return output;

for (const project of fs.readdirSync(ROOT, { withFileTypes: true })) {
  if (!project.isDirectory()) continue;
  const projectDir = path.join(ROOT, project.name);

  for (const jobEntry of fs.readdirSync(projectDir, { withFileTypes: true })) {
    if (!jobEntry.isDirectory()) continue;
    const jobDir = path.join(projectDir, jobEntry.name);
    const jobPath = path.join(jobDir, 'job.json');
    if (!fs.existsSync(jobPath)) continue;

    let job;
    try {
      job = readJson(jobPath);
    } catch {
      continue;
    }

    const donePath = path.join(jobDir, '.done');
    const manifestPath = path.join(jobDir, 'result_manifest.json');
    const callbackSentPath = path.join(jobDir, '.callback_sent');
    if (
      fs.existsSync(callbackSentPath) &&
      (fs.existsSync(donePath) || fs.existsSync(path.join(jobDir, '.failed'))) &&
      fs.existsSync(manifestPath)
    ) {
      continue;
    }

    // partial 只记录进度，不再阻止终态失败回调。
    const accepted = [];
    const failed = [];
    const missing = [];
    const statusDir = path.join(jobDir, '_status');

    for (const asset of job.assets ?? []) {
      const statusPath = path.join(statusDir, `${asset.asset_id}.json`);
      if (!fs.existsSync(statusPath)) {
        missing.push(asset.asset_id);
        continue;
      }

      let record;
      try {
        record = readJson(statusPath);
      } catch (error) {
        failed.push({
          asset_id: asset.asset_id,
          final_status: 'failed_invalid_status_file',
          final_reason: error.message,
        });
        continue;
      }

      if (!usableStatuses.has(record.final_status)) {
        failed.push({
          asset_id: asset.asset_id,
          filename: asset.filename,
          final_status: record.final_status ?? 'failed_unknown',
          final_reason: record.final_reason ?? '资产没有可用图片',
        });
        continue;
      }

      const imagePath = path.resolve(jobDir, asset.filename);
      const safeAssetsRoot = path.resolve(jobDir) + path.sep;
      if (!imagePath.startsWith(safeAssetsRoot) || !fs.existsSync(imagePath)) {
        failed.push({
          asset_id: asset.asset_id,
          filename: asset.filename,
          final_status: 'failed_missing_final_image',
          final_reason: '状态记录存在，但正式图片不存在',
        });
        continue;
      }

      const stat = fs.statSync(imagePath);
      if (!stat.isFile() || stat.size <= 0) {
        failed.push({
          asset_id: asset.asset_id,
          filename: asset.filename,
          final_status: 'failed_invalid_final_image',
          final_reason: '正式图片为空或不是普通文件',
        });
        continue;
      }

      const hash = sha256(imagePath);
      if (record.sha256 && record.sha256 !== hash && `sha256:${record.sha256}` !== hash) {
        failed.push({
          asset_id: asset.asset_id,
          filename: asset.filename,
          final_status: 'failed_final_image_hash_mismatch',
          final_reason: '正式图片 SHA256 与状态记录不一致',
        });
        continue;
      }

      accepted.push({
        asset_id: asset.asset_id,
        parent_asset_id: asset.parent_asset_id ?? null,
        family_id: asset.family_id ?? null,
        asset_code: asset.asset_code ?? null,
        generation_stage: asset.generation_stage ?? 'derived',
        category: asset.category,
        payload_sha256: job.payload_sha256 ?? asset.payload_sha256 ?? null,
        asset_role: asset.asset_role ?? null,
        asset_kind: asset.asset_kind ?? null,
        angle_id: asset.angle_id ?? null,
        layout_type: asset.layout_type ?? null,
        contains_multiple_independent_assets: asset.contains_multiple_independent_assets === true,
        name: asset.name,
        filename: asset.filename,
        relative_path: asset.filename,
        absolute_path: imagePath,
        aspect_ratio: asset.aspect_ratio ?? null,
        lock_id: asset.lock_id ?? null,
        lock_hash: asset.lock_hash ?? null,
        prompt_policy: asset.prompt_policy ?? null,
        anchor_roles: asset.anchor_roles ?? [],
        depends_on: asset.depends_on ?? [],
        reference_inputs: asset.reference_inputs ?? [],
        reference_images: record.reference_images ?? asset.reference_images ?? [],
        resolved_reference_inputs: record.resolved_reference_inputs ?? [],
        file_size: stat.size,
        sha256: hash,
        n8n_review_score:
          record.review_score !== null &&
          record.review_score !== undefined &&
          Number.isFinite(Number(record.review_score))
            ? Number(record.review_score)
            : null,
        qa_evidence: record.qa_evidence ?? null,
        image_generation_count: Number(record.image_generation_count ?? 0),
        final_status: record.final_status,
        acceptance_mode: record.acceptance_mode ?? null,
        fallback_reason: record.fallback_reason ?? null,
        model_route_profile: record.model_route_profile ?? job.model_routing?.active_profile ?? null,
        selected_route_id: record.selected_route_id ?? null,
        generation_provider: record.generation_provider ?? null,
        provider_model: record.provider_model ?? null,
        provider_cost_tier: record.provider_cost_tier ?? null,
        review_slot_id: record.review_slot_id ?? null,
        review_provider: record.review_provider ?? job.review_routing?.provider ?? null,
        review_model: record.review_model ?? job.review_routing?.model ?? null,
      });
    }

    const dependencyStates = readDependencyStates(jobDir);
    let registryInfo = updateReferenceRegistry(projectDir, job, accepted, failed);

    const autoRepairedAssets = [];
    for (const assetId of missing) {
      const asset = (job.assets ?? []).find((item) => item.asset_id === assetId);
      if (!asset) continue;
      const result = repairMissingAsset(jobDir, job, asset);
      if (result.repaired) {
        autoRepairedAssets.push({ asset_id: assetId, ...result });
      }
    }

const queueCount = countJson(path.join(jobDir, '_queue'));
    const runningCount = countJson(path.join(jobDir, '_running'));
    const strictAccepted = accepted.filter((item) => item.final_status === 'accepted');
    const fallbackAccepted = accepted.filter((item) => item.final_status !== 'accepted');
    const strictCount = strictAccepted.length;
    const fallbackCount = fallbackAccepted.length;
    const complete =
      strictCount === Number(job.expected_count) &&
      fallbackCount === 0 &&
      failed.length === 0 &&
      missing.length === 0;
    const terminalFailure =
      !complete &&
      autoRepairedAssets.length === 0 &&
      queueCount === 0 &&
      runningCount === 0 &&
      (fallbackCount > 0 || failed.length > 0 || missing.length > 0);
    const now = new Date().toISOString();
    const fallbackFailures = fallbackAccepted.map((item) => ({
      asset_id: item.asset_id,
      filename: item.filename,
      final_status: item.final_status,
      final_reason: item.fallback_reason || '资产只有临时候选，没有通过严格质检'
    }));
const terminalFailures = [...failed, ...fallbackFailures];
    const missingFailures = terminalFailure
      ? missing.map((assetId) => ({
          asset_id: assetId,
          final_status: 'failed_missing_status_after_repair',
          final_reason: '缺少资产状态且孤儿自动修复预算已耗尽'
        }))
      : [];
    if (missingFailures.length > 0) {
      terminalFailures.push(...missingFailures);
      registryInfo = updateReferenceRegistry(projectDir, job, accepted, [...failed, ...missingFailures]);
    }

    const progress = {
      schema_version: '3.1',
      project_id: job.project_id,
      job_id: job.job_id,
      payload_sha256: job.payload_sha256 ?? null,
      status: complete ? 'completed' : terminalFailure ? 'failed' : 'processing',
      expected_count: Number(job.expected_count),
      accepted_count: accepted.length,
      strict_accepted_count: strictCount,
      fallback_count: fallbackCount,
      failed_count: terminalFailures.length,
      missing_count: missing.length,
      queued_count: queueCount,
      running_count: runningCount,
      all_required_assets_approved: complete,
      dependency_waiting_count: dependencyStates.filter((item) => item.state === 'waiting').length,
      dependency_failed_count: dependencyStates.filter((item) => item.state === 'failed').length,
      dependency_states: dependencyStates,
      reference_registry_path: registryInfo.registryPath,
      reference_registry_summary: registryInfo,
      missing_assets: missing,
      failed_assets: terminalFailures,
      auto_repaired_assets: autoRepairedAssets,
      updated_at: now,
    };
    atomicJson(path.join(jobDir, 'progress.json'), progress);

    if (autoRepairedAssets.length > 0) {
      const partialPath = path.join(jobDir, '.partial');
      if (fs.existsSync(partialPath)) fs.unlinkSync(partialPath);
      continue;
    }

    if (!complete && !terminalFailure) {
      atomicJson(path.join(jobDir, '.partial'), {
        ...progress,
        status: 'processing',
        reason: '任务仍在队列、运行中或等待依赖',
      });
      continue;
    }

    const finalStatus = complete ? 'completed' : 'failed';
    const manifest = {
      schema_version: '3.1',
      project_id: job.project_id,
      job_id: job.job_id,
      payload_sha256: job.payload_sha256 ?? null,
      status: finalStatus,
      created_at: now,
      expected_count: Number(job.expected_count),
      accepted_count: accepted.length,
      strict_accepted_count: strictCount,
      fallback_count: fallbackCount,
      failed_count: terminalFailures.length,
      missing_count: missing.length,
      all_assets_complete: complete,
      all_required_assets_approved: complete,
      failure_reason: complete ? null : 'required_assets_not_strictly_approved',
      dependency_graph_filename: 'asset_dependency_graph.json',
      reference_plan_filename: 'reference_plan.json',
      reference_registry_filename: '../reference_registry.json',
      reference_registry_path: registryInfo.registryPath,
      reference_registry_summary: registryInfo,
      model_route_profile: job.model_routing?.active_profile ?? null,
      review_routing: job.review_routing ?? null,
      review_provider_summary: accepted.reduce((summary, item) => {
        const key = `${item.review_provider || 'unknown'}::${item.review_model || 'unknown'}`;
        summary[key] = (summary[key] ?? 0) + 1;
        return summary;
      }, {}),
      provider_summary: accepted.reduce((summary, item) => {
        const key = `${item.generation_provider || 'unknown'}::${item.provider_model || 'unknown'}`;
        summary[key] = (summary[key] ?? 0) + 1;
        return summary;
      }, {}),
      assets: accepted,
      failed_assets: terminalFailures,
      missing_assets: missing,
    };
    atomicJson(manifestPath, manifest);
    const markerPath = path.join(jobDir, complete ? '.done' : '.failed');
    atomicJson(markerPath, {
      schema_version: '3.1',
      project_id: job.project_id,
      job_id: job.job_id,
      payload_sha256: job.payload_sha256 ?? null,
      status: finalStatus,
      expected_count: Number(job.expected_count),
      accepted_count: accepted.length,
      strict_accepted_count: strictCount,
      fallback_count: fallbackCount,
      failed_count: terminalFailures.length,
      missing_count: missing.length,
      all_required_assets_approved: complete,
      manifest: 'result_manifest.json',
      reference_registry: '../reference_registry.json',
      reference_registry_path: registryInfo.registryPath,
      completed_at: now,
    });
    const partialPath = path.join(jobDir, '.partial');
    if (fs.existsSync(partialPath)) fs.unlinkSync(partialPath);

    if (!acquireCallback(jobDir)) continue;
    output.push({
      json: {
        event: complete ? 'n8n_asset_generation_completed' : 'n8n_asset_generation_failed',
        continuity_mode: true,
        project_id: job.project_id,
        job_id: job.job_id,
        payload_sha256: job.payload_sha256 ?? null,
        status: finalStatus,
        expected_count: Number(job.expected_count),
        accepted_count: accepted.length,
        strict_accepted_count: strictCount,
        fallback_count: fallbackCount,
        failed_count: terminalFailures.length,
        missing_count: missing.length,
        all_assets_complete: complete,
        all_required_assets_approved: complete,
        failure_reason: complete ? null : 'required_assets_not_strictly_approved',
        failed_assets: terminalFailures,
        missing_assets: missing,
        manifest_filename: 'result_manifest.json',
        marker_filename: complete ? '.done' : '.failed',
        reference_registry_filename: '../reference_registry.json',
        reference_registry_path: registryInfo.registryPath,
        approved_reference_count: registryInfo.approved_count,
        provisional_reference_count: registryInfo.provisional_count,
        _internal_job_dir: jobDir,
      }
    });
  }
}

return output;

const fs = require('fs');
  const path = require('path');

  const source = $('扫描任务并生成完成清单').item.json;
  const jobDir = source._internal_job_dir;
  const inflightPath = path.join(jobDir, '.callback_inflight');
  const statusCode = Number($json.statusCode ?? 0);
  const successful = statusCode >= 200 && statusCode < 300 && !$json.error;

  function atomicJson(filePath, value) {
    const tmp = `${filePath}.${Date.now()}.${Math.random().toString(16).slice(2)}.tmp`;
    fs.writeFileSync(tmp, JSON.stringify(value, null, 2), 'utf8');
    fs.renameSync(tmp, filePath);
  }

  const result = {
    project_id: source.project_id,
    job_id: source.job_id,
    status_code: statusCode,
    successful,
    response: $json.body ?? $json.data ?? null,
    error: $json.error ?? null,
    attempted_at: new Date().toISOString(),
  };

  if (successful) {
    atomicJson(path.join(jobDir, '.callback_sent'), result);
    const errorPath = path.join(jobDir, '.callback_error.json');
    if (fs.existsSync(errorPath)) fs.unlinkSync(errorPath);
  } else {
    atomicJson(path.join(jobDir, '.callback_error.json'), result);
  }

  if (fs.existsSync(inflightPath)) fs.unlinkSync(inflightPath);

  return [{
    json: {
      event: successful
        ? 'openclaw_callback_sent'
        : 'openclaw_callback_failed_will_retry',
      project_id: source.project_id,
      job_id: source.job_id,
      status_code: statusCode,
      successful,
    }
  }];
